import Typography from "@mui/material/Typography";
import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";
import Box from "@mui/material/Box";
import IconButton from "@mui/material/IconButton";
import CustomDataGrid from "src/@core/components/data-grid";
import Chip from "@mui/material/Chip";
import { styled } from "@mui/material/styles";
import { MEDIA_URL } from "src/network/endpoints";
import moment from "moment";
import { Avatar } from "@mui/material";
import { useEffect, useState } from "react";

function TableBlog({
  rows,
  totalCount,
  setCurrentPage,
  currentPage,
  setPageSize,
  pageSize,
  loading,
  toggleEdit,
  toggleDelete,
  status,
}) {
  const statusColors = {
    inactive: "#3A3541AD",
    active: "#66bb6a",
  };
  const CustomChip = styled(Chip)(({ label }) => ({
    backgroundColor: statusColors[label] || statusColors.default,
    textTransform: "capitalize",
    color: "#fff",
    width: "100px",
  }));
  const [activeData, setActiveData] = useState([]);
  const [inActiveData, setInActiveData] = useState([]);
  useEffect(() => {
    const activeRows = rows.filter((row) => row.status === "active");
    setActiveData(activeRows);
    const inActiveRows = rows.filter((row) => row.status === "inactive");
    setInActiveData(inActiveRows);
  }, [rows]);
  const displayedRows =
    status === "active"
      ? activeData
      : status === "inactive"
      ? inActiveData
      : rows;

  return (
    <CustomDataGrid
      loading={loading}
      rowCount={totalCount}
      rows={displayedRows}
      columns={[
        {
          field: "author_name",
          minWidth: 150,
          flex: 1,
          sortable: false,
          headerName: "Author",
          renderCell: ({ row }) => (
            <Typography noWrap variant="body2" title={row.author_name}>
              {row.author_name}
            </Typography>
          ),
        },
        {
          field: "title",
          minWidth: 250,
          flex: 1,
          sortable: false,
          headerName: "Title",
          renderCell: ({ row }) => (
            <Typography noWrap variant="body2" title={row.title}>
              {row.title}
            </Typography>
          ),
        },
        {
          field: "author_image",
          minWidth: 180,
          flex: 1,
          sortable: false,
          headerName: "Author Image",
          renderCell: ({ row }) => <Avatar src={row.author_image} />,
        },
        {
          field: "category",
          minWidth: 180,
          flex: 1,
          sortable: false,
          headerName: "Category",
          renderCell: ({ row }) => (
            <Typography noWrap variant="body2" title={row.category}>
              {row.category}
            </Typography>
          ),
        },
        // {
        //   field: "image",
        //   flex: 0.1,
        //   minWidth: 150,
        //   sortable: false,
        //   headerName: "Image",
        //   renderCell: ({ row }) => (
        //     <img
        //       alt=""
        //       src={`${MEDIA_URL}${row.image}`}
        //       style={{ height: "30px", width: "50px" }}
        //     />
        //   ),
        // },
        // {
        //   field: "discription",
        //   minWidth: 400,
        //   sortable: false,
        //   headerName: "Description",
        //   renderCell: ({ row }) => (
        //     <Typography noWrap variant="body2" title={row.discription}>
        //       <div
        //         className="blog_____content"
        //         dangerouslySetInnerHTML={{
        //           __html: row.discription,
        //         }}
        //       />
        //     </Typography>
        //   ),
        // },
        {
          field: "status",
          minWidth: 180,
          flex: 1,
          sortable: false,
          headerName: "Status",
          renderCell: ({ row }) => <CustomChip label={row.status} />,
        },
        {
          field: "Actions",
          flex: 0,
          minWidth: 170,
          sortable: false,
          headerName: "Actions",
          renderCell: ({ row }) => (
            <Box display="flex" alignItems="center" gap="10px">
              <IconButton
                size="small"
                color="primary"
                variant="outlined"
                onClick={(e) => toggleEdit(e, "edit", row)}
              >
                <EditIcon />
              </IconButton>
              <IconButton
                size="small"
                color="secondary"
                onClick={(e) => toggleDelete(e, row)}
              >
                <DeleteIcon />
              </IconButton>
            </Box>
          ),
        },
      ]}
      currentPage={currentPage}
      pageSize={pageSize}
      setCurrentPage={setCurrentPage}
      setPageSize={setPageSize}
    />
  );
}

export default TableBlog;
